241	const MAIN_PORTFOLIO_FALLBACK_VIDEO = "/resource/video/why_video_1.mp4";
242	
243	const _portfolioHoverCleanups: Array<() => void> = [];
244	
245	(function initPortfolioHover(): void {
246	  const items = document.querySelectorAll<HTMLLIElement>(
247	    ".no-main-portfolio__item[data-video]",
248	  );
249	  items.forEach((li) => {
250	    const videoUrl = li.dataset.video || MAIN_PORTFOLIO_FALLBACK_VIDEO;
251	    const figure = li.querySelector<HTMLElement>(".no-sub-gallery-item__img");
252	    const video = li.querySelector<HTMLVideoElement>("video");
253	    if (!figure || !video) return;
254	
255	    let isHovered = false;
256	    let pendingPlay: Promise<void> | null = null;
257	
258	    const show = (): void => {
259	      if (isHovered) figure.classList.add("is-video-active");
260	    };
261	    const hideNow = (): void => {
262	      figure.classList.remove("is-video-active");
263	    };
264	    const safePause = (): void => {
265	      video.pause();
266	      video.currentTime = 0;
267	    };
268	    const drainAndPause = (): void => {
269	      const p = pendingPlay;
270	      pendingPlay = null;
271	      if (p !== null) {
272	        void p.then(() => {
273	          if (!isHovered) safePause();
274	        });
275	      } else {
276	        safePause();
277	      }
278	    };
279	
280	    const onEnter = (): void => {
281	      isHovered = true;
282	      if (!video.src) {
283	        video.src = videoUrl;
284	        video.load();
285	      }
286	      pendingPlay = video.play().catch(() => undefined);
287	      if (video.readyState >= 3) {
288	        show();
289	      } else {
290	        video.addEventListener("canplay", show, { once: true });
291	      }
292	    };
293	    const onLeave = (): void => {
294	      isHovered = false;
295	      video.removeEventListener("canplay", show);
296	      hideNow();
297	      drainAndPause();
298	    };
299	
300	    li.addEventListener("pointerenter", onEnter);
301	    li.addEventListener("pointerleave", onLeave);
302	    _portfolioHoverCleanups.push(() => {
303	      isHovered = false;
304	      video.removeEventListener("canplay", show);
305	      figure.classList.remove("is-video-active");
306	      drainAndPause();
307	      li.removeEventListener("pointerenter", onEnter);
308	      li.removeEventListener("pointerleave", onLeave);
309	    });
310	  });
311	})();
